package org.example;

// Import BigDecimal for accurate monetary values.
import java.math.BigDecimal;

public class Account {

    // Unique identifier generated by PostgreSQL.
    private long accountId;

    // Unique bank account number.
    private String accountNumber;

    // Full name of the account holder.
    private String accountName;

    // Account balance.
    private BigDecimal balance;

    // Current account status.
    private String status;

    // Constructor used to create Account objects.
    public Account(
            long accountId,
            String accountNumber,
            String accountName,
            BigDecimal balance,
            String status
    ) {

        // Initialize the account ID.
        this.accountId = accountId;

        // Initialize the account number.
        this.accountNumber = accountNumber;

        // Initialize the account holder's name.
        this.accountName = accountName;

        // Initialize the account balance.
        this.balance = balance;

        // Initialize the account status.
        this.status = status;
    }

    // Return the account ID.
    public long getAccountId() {
        return accountId;
    }

    // Return the account number.
    public String getAccountNumber() {
        return accountNumber;
    }

    // Return the account holder's name.
    public String getAccountName() {
        return accountName;
    }

    // Return the account balance.
    public BigDecimal getBalance() {
        return balance;
    }

    // Return the account status.
    public String getStatus() {
        return status;
    }

    // Generate a readable representation of the account.
    @Override
    public String toString() {

        return "\nAccount ID: " + accountId +
                "\nAccount Number: " + accountNumber +
                "\nAccount Name: " + accountName +
                "\nBalance: " + balance +
                "\nStatus: " + status;
    }
}
